//! Actual pinned-Go WHIP HTTP envelope comparison. The rows are captured from the
//! fixed Go server (`pkg/service/whipservice.go` at v1.13.10, e5655ac2) and read back
//! here; nothing is generated by this crate, so a Rust-side change cannot quietly
//! redefine the contract. Requests run through the full middleware chain
//! ([`crate::http::router`]), so the grant a row describes reaches the handler the same
//! way `APIKeyAuthMiddleware` delivers it upstream.
use super::*;
use axum::body::Body;
use rtc_core::permission::{Grants, VideoGrant};
use tower::ServiceExt;

/// One captured Go response for one stimulus.
#[derive(serde::Deserialize)]
struct Row {
    id: String,
    method: String,
    path: String,
    #[serde(default)]
    content_type: Option<String>,
    #[serde(default)]
    if_match: Option<String>,
    /// The token's identity claim, or empty for a token with no subject.
    #[serde(default)]
    identity: String,
    /// The token's `video` claim object, or null to present no token at all.
    #[serde(default)]
    video: Option<VideoGrant>,
    status: u16,
    #[serde(default)]
    response_content_type: Option<String>,
    #[serde(default)]
    error: Option<String>,
    #[serde(default)]
    empty_body: bool,
}

const ROW_KEY_ID: &str = "whip-row-key";
const ROW_KEY_SECRET: &str = "whip-row-secret-only-for-local-oracle-rows";

/// Mint the row's token with the project minter, so the claims that reach the verifier
/// are the same bytes an official client would send.
fn token_for(row: &Row) -> String {
    let keys = Arc::new(crate::auth::KeyStore::new(vec![(
        ROW_KEY_ID.into(),
        ROW_KEY_SECRET.into(),
    )]));
    let minter = crate::auth::TokenMinter::new(keys);
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_secs() as i64;
    minter
        .mint(
            ROW_KEY_ID,
            &crate::auth::TokenClaims {
                identity: row.identity.clone(),
                video: row.video.clone(),
                ..Default::default()
            },
            Duration::from_secs(600),
            now,
        )
        .expect("row token mints")
}

async fn send(state: &AppState, row: &Row) -> Response {
    let mut uri = row.path.clone();
    if row.video.is_some() {
        // Percent-encode nothing: a JWT is already URL-safe base64.
        uri.push_str(&format!("?access_token={}", token_for(row)));
    }
    let mut builder = axum::http::Request::builder()
        .method(row.method.as_str())
        .uri(uri);
    if let Some(ct) = &row.content_type {
        builder = builder.header("content-type", ct.as_str());
    }
    if let Some(tag) = &row.if_match {
        builder = builder.header("if-match", tag.as_str());
    }
    crate::http::router(state.clone())
        .oneshot(builder.body(Body::empty()).unwrap())
        .await
        .unwrap()
}

/// Every pinned-Go row's status, Content-Type and JSON error envelope, driven through
/// the real chain. Rows whose body is not an error envelope (the 201 SDP answer, the
/// 200 ICE-restart fragment) need live media and are out of scope here.
#[test]
#[ignore = "requires coordinator-run actual pinned-Go WHIP HTTP envelope rows"]
fn whip_http_envelope_rows_match_pinned_go() {
    let text = std::fs::read_to_string(
        std::env::var("WHIP_HTTP_GO_ROWS").expect("actual pinned-Go rows path"),
    )
    .unwrap();
    let rows: Vec<Row> = text
        .lines()
        .filter(|line| !line.trim().is_empty())
        .map(|line| serde_json::from_str(line).unwrap())
        .collect();
    assert!(!rows.is_empty(), "pinned-Go rows must be provided");
    let rt = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .unwrap();
    rt.block_on(async {
        let (mut state, net) = crate::test_support::state_with_keys(vec![(
            ROW_KEY_ID.to_string(),
            ROW_KEY_SECRET.to_string(),
        )])
        .await;
        for row in &rows {
            let response = send(&state, row).await;
            assert_eq!(u16::from(response.status()), row.status, "{} status", row.id);
            let content_type = response
                .headers()
                .get(header::CONTENT_TYPE)
                .map(|v| v.to_str().unwrap().to_owned());
            assert_eq!(
                content_type.as_deref(),
                row.response_content_type.as_deref(),
                "{} content-type",
                row.id
            );
            let body = axum::body::to_bytes(response.into_body(), 1 << 20)
                .await
                .unwrap();
            if row.empty_body {
                assert!(body.is_empty(), "{} body must be empty", row.id);
                continue;
            }
            // Go's json.Encoder writes the envelope with a trailing newline.
            assert_eq!(
                String::from_utf8_lossy(&body),
                format!(
                    "{{\"error\":{}}}\n",
                    go_json_quote(row.error.as_deref().unwrap_or_default())
                ),
                "{} body",
                row.id
            );
        }
        state.manager.close_all().await;
        state.agents.shutdown().await;
        state.shutdown_whip().await;
        net.shutdown();
    });
}

/// Go `encoding/json` escapes `<`, `>` and `&`; the handler under test reproduces that,
/// so the reference quoting is written independently here.
fn go_json_quote(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '<' => out.push_str("\\u003c"),
            '>' => out.push_str("\\u003e"),
            '&' => out.push_str("\\u0026"),
            _ => out.push(c),
        }
    }
    out.push('"');
    out
}

/// Silence an unused-import warning when the rows are absent: `Grants` documents the
/// shape the handlers read out of the verified token.
#[allow(dead_code)]
fn _grants_shape(grants: &Grants) -> &VideoGrant {
    &grants.video
}
